<?php
declare(strict_types=1);namespace App\Services\TeachingAssignments;use App\Models\{TeachingAssignmentSet,User};use App\Services\Exports\DatabaseXlsxService;use Symfony\Component\HttpFoundation\BinaryFileResponse;
class TeachingAssignmentExportService {public function __construct(private DatabaseXlsxService $xlsx){}public function download(User $actor,TeachingAssignmentSet $set):BinaryFileResponse{$set->load(['academicYear','assignments.classroom.gradeLevel','assignments.subject','assignments.personnel','additionalDuties.personnel','additionalDuties.classroom']);$classrooms=[['Rombel','Program','Mata Pelajaran','Guru','JP','Peran']];$teachers=[['Guru','Rombel','Mata Pelajaran','JP']];foreach($set->assignments as $a){$classrooms[]=[$a->classroom->display_name,$a->classroom->program_type->label(),$a->subject->name,$a->personnel->full_name,$a->weekly_periods,$a->is_primary?'Guru Utama':'Guru Pendamping'];$teachers[]=[$a->personnel->full_name,$a->classroom->display_name,$a->subject->name,$a->weekly_periods];}$duties=[['Guru','Tugas','Rombel','Ekuivalensi JP']];foreach($set->additionalDuties as $d)$duties[]=[$d->personnel->full_name,$d->duty_name,$d->classroom?->display_name??'—',$d->equivalent_periods];$summary=[['Tahun Ajaran',$set->academicYear->name],['Nama Set',$set->name],['Status',ucfirst($set->status)]];$path=tempnam(sys_get_temp_dir(),'assignments').'.xlsx';$this->xlsx->write(['Ringkasan'=>$summary,'Per Kelas'=>$classrooms,'Per Guru'=>$teachers,'Tugas Tambahan'=>$duties],$path);$year=str_replace(['/',' '],'-',$set->academicYear->name);activity('teaching-assignments')->causedBy($actor)->performedOn($set)->log('Mengekspor pembagian tugas.');return response()->download($path,"pembagian-tugas-{$year}.xlsx")->deleteFileAfterSend(true);}}
